function resolveTreeCollision(model,previous,radius){
 if(model.position.y>.2)return;
 for(let pass=0;pass<2;pass++)for(const t of trees){
  if(t.hp<=0||t.fall>.35)continue;
  const minimum=(t.radius||1.1)+radius,dx=model.position.x-t.x,dz=model.position.z-t.z,distance=Math.hypot(dx,dz);
  if(distance>=minimum)continue;
  let nx=dx/distance,nz=dz/distance;
  if(distance<.001){const ox=previous.x-t.x,oz=previous.z-t.z,length=Math.hypot(ox,oz)||1;nx=ox/length;nz=oz/length;}
  model.position.x=t.x+nx*minimum;model.position.z=t.z+nz*minimum;
 }
}

function resolveVillageCollision(model,previous,radius){
 for(const obstacle of villageObstacles){const minimum=obstacle.radius+radius,dx=model.position.x-obstacle.x,dz=model.position.z-obstacle.z,distance=Math.hypot(dx,dz);if(distance>=minimum)continue;let nx=dx/distance,nz=dz/distance;if(distance<.001){const ox=previous.x-obstacle.x,oz=previous.z-obstacle.z,length=Math.hypot(ox,oz)||1;nx=ox/length;nz=oz/length}model.position.x=obstacle.x+nx*minimum;model.position.z=obstacle.z+nz*minimum;}
}

function animateRig(model,motion,state,dt,dead=false){
 const u=model.userData;u.animPhase+=dt*(5.5+motion*3.5);u.motion=THREE.MathUtils.lerp(u.motion,clamp(motion/2,0,1),1-Math.exp(-dt*9));
 if(dead){if(!u.deadStarted){u.deadStarted=true;u.death=0;model.rotation.z=0}u.death=clamp(u.death+dt*2.3,0,1);const fall=u.death*u.death*(3-2*u.death);model.rotation.z=fall*1.48;model.position.y=.03+Math.sin(fall*Math.PI)*.09;return;}
 const stride=Math.sin(u.animPhase),walk=u.motion,bob=Math.abs(Math.sin(u.animPhase))*walk*.055;
 u.legs.forEach((leg,i)=>{leg.rotation.x=THREE.MathUtils.lerp(leg.rotation.x,stride*(i?-.66:.66)*walk,1-Math.exp(-dt*13));leg.rotation.z=(i?-.035:.035)*walk;});
 const attacking=u.strike>0;u.strike=Math.max(0,(u.strike||0)-dt*2.4);
 u.arms.forEach((arm,i)=>{const swing=attacking&&i===1?-1.5*(1-Math.abs(u.strike-.5)*2):stride*(i?.42:-.42)*walk;arm.rotation.x=THREE.MathUtils.lerp(arm.rotation.x,swing,1-Math.exp(-dt*15));});
 u.body.position.y=u.bodyBase+bob;u.body.rotation.z=Math.sin(u.animPhase*.5)*.025*walk;u.head.position.y=u.headBase+bob*.75;u.head.rotation.y=['panic','danger','investigate','search'].includes(state)?Math.sin(elapsed*5+model.id)*.48:Math.sin(u.animPhase*.22)*.08;
 model.rotation.z=THREE.MathUtils.lerp(model.rotation.z,state==='flee'?-.06:0,1-Math.exp(-dt*7));
}

